  "signal_basis": {
    "component_id": "C068_signal_basis",
    "value": "Assess whether the canary changes the predicted phase and overall tail without increasing failures or unfinished exports. Rare delays require sufficient comparable exposure; a short clean canary cannot establish resolution, and inadequate exposure or coverage makes the result inconclusive.",
    "scope": "Assessment of the canary over a specified observation window and required exposure, within the stated safety bounds.",
